include <p>using namespace std; class Solution{     public:     vector twoS(vector arr, int target){         vector solu;         int n = arr.size(); <pre><code>    sort(arr.begin(), arr.end());
    int l = 0;
    int r = n-1;
    while(l&lt;r){
        int sum = arr[l]+arr[r];
        if(sum==target){
            solu.push_back(arr[l]);
            solu.push_back(arr[r]);
            return solu;
        }
        else if(sum&lt;target){
            l++;
        }
        else{
            r--;
        }
    }
    return solu;
}
